package main

import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	reader := bufio.NewReader(os.Stdin)
	writer := bufio.NewWriter(os.Stdout)
	defer writer.Flush()

	var n, m int
	fmt.Fscan(reader, &n, &m)

	f := make([]int, n+1)
	for i := 1; i <= n; i++ {
		fmt.Fscan(reader, &f[i])
	}

	adj := make([][]int, n+1)
	revAdj := make([][]int, n+1)
	for i := 0; i < m; i++ {
		var a, b int
		fmt.Fscan(reader, &a, &b)
		adj[a] = append(adj[a], b)
		revAdj[b] = append(revAdj[b], a)
	}

	// Step 1: Find all nodes reachable from any assignment node (f=1)
	reachableFromAssign := make([]bool, n+1)
	q := []int{}
	for i := 1; i <= n; i++ {
		if f[i] == 1 {
			reachableFromAssign[i] = true
			q = append(q, i)
		}
	}
	for len(q) > 0 {
		u := q[0]
		q = q[1:]
		for _, v := range adj[u] {
			if !reachableFromAssign[v] {
				reachableFromAssign[v] = true
				q = append(q, v)
			}
		}
	}

	// Step 2: Find all nodes that can reach a usage node (f=2)
	canReachUse := make([]bool, n+1)
	q = []int{}
	for i := 1; i <= n; i++ {
		if f[i] == 2 {
			canReachUse[i] = true
			q = append(q, i)
		}
	}
	for len(q) > 0 {
		u := q[0]
		q = q[1:]
		for _, v := range revAdj[u] {
			if !canReachUse[v] {
				canReachUse[v] = true
				q = append(q, v)
			}
		}
	}

	// Step 3: Find nodes that are reachable from an assignment node and can reach a usage node
	// But also, the path must not contain any other assignment node except the start
	// So we need to find nodes that are on a path from some assignment node to some usage node,
	// where the path doesn't contain any other assignment node

	// To do this, we need to find nodes that are reachable from an assignment node,
	// can reach a usage node, and are not an assignment node themselves (except possibly the start)

	// Actually, let's think differently:
	// A node v is "interesting" if there exists a path from some assignment node u to some usage node w,
	// such that v is on this path, and no node on this path (except u) is an assignment node.

	// This means:
	// 1. v must be reachable from some assignment node u (where u is the only assignment node on the path)
	// 2. v must be able to reach some usage node w (without passing through any assignment node except u)

	// Let's compute:
	// - For each node, can it reach a usage node without passing through any assignment node?
	//   (call this canReachUseNoAssign)
	// - For each node, is it reachable from an assignment node without passing through any assignment node?
	//   (call this reachableFromAssignNoAssign)

	// But this is tricky because the assignment node is the start.

	// Alternative approach:
	// 1. Remove all assignment nodes except one at a time? No, too slow.
	// 2. Think of it as: a node v is interesting if:
	//    a. There exists an assignment node u such that u can reach v
	//    b. v can reach a usage node w
	//    c. On the path from u to v, there's no other assignment node
	//    d. On the path from v to w, there's no assignment node

	// Let's compute:
	// - reachableFromAssignNoAssign[v]: true if v is reachable from some assignment node via a path
	//   that doesn't contain any assignment node except the start
	// - canReachUseNoAssign[v]: true if v can reach some usage node via a path that doesn't contain
	//   any assignment node

	// For canReachUseNoAssign:
	// Start BFS/DFS from usage nodes in reverse graph, but stop at assignment nodes
	canReachUseNoAssign := make([]bool, n+1)
	q = []int{}
	for i := 1; i <= n; i++ {
		if f[i] == 2 {
			canReachUseNoAssign[i] = true
			q = append(q, i)
		}
	}
	for len(q) > 0 {
		u := q[0]
		q = q[1:]
		for _, v := range revAdj[u] {
			if f[v] == 1 {
				continue // Don't traverse through assignment nodes
			}
			if !canReachUseNoAssign[v] {
				canReachUseNoAssign[v] = true
				q = append(q, v)
			}
		}
	}

	// For reachableFromAssignNoAssign:
	// Start BFS/DFS from assignment nodes, but don't traverse through other assignment nodes
	reachableFromAssignNoAssign := make([]bool, n+1)
	q = []int{}
	for i := 1; i <= n; i++ {
		if f[i] == 1 {
			reachableFromAssignNoAssign[i] = true
			q = append(q, i)
		}
	}
	for len(q) > 0 {
		u := q[0]
		q = q[1:]
		for _, v := range adj[u] {
			if f[v] == 1 {
				continue // Don't traverse through assignment nodes
			}
			if !reachableFromAssignNoAssign[v] {
				reachableFromAssignNoAssign[v] = true
				q = append(q, v)
			}
		}
	}

	// A node v is interesting if:
	// - It's an assignment node and it can reach a usage node without passing through another assignment node
	// - It's not an assignment node, is reachable from an assignment node without passing through another assignment node,
	//   and can reach a usage node without passing through any assignment node

	result := make([]int, n+1)
	for i := 1; i <= n; i++ {
		if f[i] == 1 {
			// Assignment node: interesting if it can reach a usage node without passing through another assignment node
			if canReachUseNoAssign[i] {
				result[i] = 1
			}
		} else {
			// Non-assignment node: interesting if reachable from an assignment node (without passing through another assignment)
			// and can reach a usage node (without passing through any assignment node)
			if reachableFromAssignNoAssign[i] && canReachUseNoAssign[i] {
				result[i] = 1
			}
		}
	}

	for i := 1; i <= n; i++ {
		fmt.Fprintln(writer, result[i])
	}
}
