package main

import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	reader := bufio.NewReader(os.Stdin)
	writer := bufio.NewWriter(os.Stdout)
	defer writer.Flush()

	var n, m int
	fmt.Fscan(reader, &n, &m)

	f := make([]int, n+1)
	for i := 1; i <= n; i++ {
		fmt.Fscan(reader, &f[i])
	}

	adj := make([][]int, n+1)
	for i := 0; i < m; i++ {
		var a, b int
		fmt.Fscan(reader, &a, &b)
		adj[a] = append(adj[a], b)
	}

	// For each node, determine if it's on a path from a 1 to a 2 with no intermediate 1s
	// We'll do BFS/DFS from each 1, tracking if we've seen another 1
	// But that's O(n*m) in worst case. Need a better approach.

	// Alternative: 
	// A node v is interesting if:
	// - v is a 1 (assignment), and there's a path from v to some 2 (use) with no 1 in between
	// - v is on a path from some 1 to some 2 with no 1 in between (except start)

	// Let's think differently:
	// 1. Find all nodes that can reach a 2 without passing through a 1 (except themselves if they're 1)
	// 2. A node is interesting if it's a 1 that can reach a 2 without intermediate 1s,
	//    or it's on such a path

	// Approach:
	// - For each node, check if it can reach a 2 without going through any 1 (except start)
	// - Then a node is interesting if:
	//   - It's a 1 and can reach a 2 without intermediate 1s
	//   - It's reachable from some 1 (that can reach a 2 without intermediate 1s) without intermediate 1s

	// Let's do reverse BFS from all 2s, marking nodes that can reach a 2 without 1s
	// Then forward BFS from all 1s that can reach 2s, marking nodes on valid paths

	// Step 1: Reverse BFS from all 2s, but stop at 1s
	canReach2 := make([]bool, n+1)
	queue := []int{}
	for i := 1; i <= n; i++ {
		if f[i] == 2 {
			canReach2[i] = true
			queue = append(queue, i)
		}
	}

	// Build reverse graph
	radj := make([][]int, n+1)
	for u := 1; u <= n; u++ {
		for _, v := range adj[u] {
			radj[v] = append(radj[v], u)
		}
	}

	// BFS in reverse, but don't traverse through 1s (except we start from 2s)
	visited := make([]bool, n+1)
	for _, node := range queue {
		visited[node] = true
	}

	for len(queue) > 0 {
		u := queue[0]
		queue = queue[1:]
		for _, v := range radj[u] {
			if !visited[v] && f[v] != 1 {
				visited[v] = true
				canReach2[v] = true
				queue = append(queue, v)
			}
		}
	}

	// Step 2: Forward BFS from all 1s that can reach a 2
	// Mark all nodes on paths from such 1s to 2s (without intermediate 1s)
	interesting := make([]bool, n+1)
	queue = []int{}
	for i := 1; i <= n; i++ {
		if f[i] == 1 && canReach2[i] {
			interesting[i] = true
			queue = append(queue, i)
		}
	}

	visited = make([]bool, n+1)
	for _, node := range queue {
		visited[node] = true
	}

	for len(queue) > 0 {
		u := queue[0]
		queue = queue[1:]
		for _, v := range adj[u] {
			if !visited[v] && f[v] != 1 {
				visited[v] = true
				interesting[v] = true
				queue = append(queue, v)
			}
		}
	}

	for i := 1; i <= n; i++ {
		if interesting[i] {
			fmt.Fprintln(writer, 1)
		} else {
			fmt.Fprintln(writer, 0)
		}
	}
}
