package main

import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	reader := bufio.NewReader(os.Stdin)
	writer := bufio.NewWriter(os.Stdout)
	defer writer.Flush()

	var n, m int
	fmt.Fscan(reader, &n, &m)

	f := make([]int, n+1)
	for i := 1; i <= n; i++ {
		fmt.Fscan(reader, &f[i])
	}

	adj := make([][]int, n+1)
	for i := 0; i < m; i++ {
		var a, b int
		fmt.Fscan(reader, &a, &b)
		adj[a] = append(adj[a], b)
	}

	// For each node, track:
	// - reachable_assign: whether there's an assignment node reachable from this node (including itself)
	// - reachable_use: whether there's a use node reachable from this node (including itself)
	// - has_assignment_before_use: whether there's a path from an assignment node to a use node passing through this node
	reachable_assign := make([]bool, n+1)
	reachable_use := make([]bool, n+1)
	result := make([]int, n+1)

	// We'll do a reverse approach:
	// First, find all nodes that can reach a use node (reachable_use)
	// Then, find all nodes that can be reached from an assignment node (reachable_assign)
	// A node is interesting if it's on a path from an assignment to a use

	// Step 1: Find nodes that can reach a use node
	// Do BFS/DFS from all use nodes in reverse graph
	rev_adj := make([][]int, n+1)
	for u := 1; u <= n; u++ {
		for _, v := range adj[u] {
			rev_adj[v] = append(rev_adj[v], u)
		}
	}

	// BFS from use nodes in reverse graph to find nodes that can reach a use
	can_reach_use := make([]bool, n+1)
	queue := []int{}
	for i := 1; i <= n; i++ {
		if f[i] == 2 {
			can_reach_use[i] = true
			queue = append(queue, i)
		}
	}

	for len(queue) > 0 {
		u := queue[0]
		queue = queue[1:]
		for _, v := range rev_adj[u] {
			if !can_reach_use[v] {
				can_reach_use[v] = true
				queue = append(queue, v)
			}
		}
	}

	// Step 2: Find nodes reachable from assignment nodes
	// BFS from assignment nodes in forward graph
	can_reach_from_assign := make([]bool, n+1)
	queue = []int{}
	for i := 1; i <= n; i++ {
		if f[i] == 1 {
			can_reach_from_assign[i] = true
			queue = append(queue, i)
		}
	}

	for len(queue) > 0 {
		u := queue[0]
		queue = queue[1:]
		for _, v := range adj[u] {
			if !can_reach_from_assign[v] {
				can_reach_from_assign[v] = true
				queue = append(queue, v)
			}
		}
	}

	// Step 3: A node is interesting if:
	// - It can be reached from an assignment node (can_reach_from_assign[i] is true)
	// - It can reach a use node (can_reach_use[i] is true)
	// - There exists a path from an assignment to a use that goes through this node
	// The third condition is automatically satisfied if both first conditions are true
	// because we can go from assignment -> this node -> use

	for i := 1; i <= n; i++ {
		if can_reach_from_assign[i] && can_reach_use[i] {
			result[i] = 1
		} else {
			result[i] = 0
		}
	}

	for i := 1; i <= n; i++ {
		fmt.Fprintln(writer, result[i])
	}
}
