	reachableFromAssign := make([]bool, n+1)
	for i := 1; i <= n; i++ {
		if f[i] == 1 {
			reachableFromAssign[i] = true
		}
	}

	queue := []int{}
	for i := 1; i <= n; i++ {
		if reachableFromAssign[i] {
			queue = append(queue, i)
		}
	}

	for len(queue) > 0 {
		u := queue[0]
		queue = queue[1:]
		for _, v := range adj[u] {
			if !reachableFromAssign[v] {
				reachableFromAssign[v] = true
				queue = append(queue, v)
			}
		}
	}

	// Step 2: Find all nodes that can reach a usage node (f[i] == 2)
	canReachUse := make([]bool, n+1)
	for i := 1; i <= n; i++ {
		if f[i] == 2 {
			canReachUse[i] = true
		}
	}

	queue = []int{}
	for i := 1; i <= n; i++ {
		if canReachUse[i] {
			queue = append(queue, i)
		}
	}

	for len(queue) > 0 {
		u := queue[0]
		queue = queue[1:]
		for _, v := range revAdj[u] {
			if !canReachUse[v] {
				canReachUse[v] = true
				queue = append(queue, v)
			}
		}
	}

	// Step 3: Find all assignment nodes (f[i] == 1)
	assignNodes := []int{}
	for i := 1; i <= n; i++ {
		if f[i] == 1 {
			assignNodes = append(assignNodes, i)
		}
	}

	// Step 4: For each assignment node, find all nodes reachable without passing through another assignment node
	visited := make([]bool, n+1)
	result := make([]int, n+1)

	for _, start := range assignNodes {
		if visited[start] {
			continue
