package main

import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	reader := bufio.NewReader(os.Stdin)
	writer := bufio.NewWriter(os.Stdout)
	defer writer.Flush()

	var n, m int
	fmt.Fscan(reader, &n, &m)

	f := make([]int, n+1)
	for i := 1; i <= n; i++ {
		fmt.Fscan(reader, &f[i])
	}

	adj := make([][]int, n+1)
	radj := make([][]int, n+1)

	for i := 0; i < m; i++ {
		var a, b int
		fmt.Fscan(reader, &a, &b)
		adj[a] = append(adj[a], b)
		radj[b] = append(radj[b], a)
	}

	// Forward BFS from all assignment nodes (f[i] == 1)
	forward := make([]bool, n+1)
	q := []int{}
	for i := 1; i <= n; i++ {
		if f[i] == 1 {
			forward[i] = true
			q = append(q, i)
		}
	}
	for len(q) > 0 {
		u := q[0]
		q = q[1:]
		for _, v := range adj[u] {
			if !forward[v] {
				forward[v] = true
				q = append(q, v)
			}
		}
	}

	// Backward BFS from all use nodes (f[i] == 2) on reversed graph
	backward := make([]bool, n+1)
	q = []int{}
	for i := 1; i <= n; i++ {
		if f[i] == 2 {
			backward[i] = true
			q = append(q, i)
		}
	}
	for len(q) > 0 {
		u := q[0]
		q = q[1:]
		for _, v := range radj[u] {
			if !backward[v] {
				backward[v] = true
				q = append(q, v)
			}
		}
	}

	// A node is interesting if it's reachable from an assignment (forward)
	// and can reach a use (backward)
	for i := 1; i <= n; i++ {
		if forward[i] && backward[i] {
			fmt.Fprintln(writer, 1)
		} else {
			fmt.Fprintln(writer, 0)
		}
	}
}
