				q = append(q, v)
			}
		}
	}

	// Step 2: Find all nodes that can reach a use node (reverse BFS from use nodes)
	canReachUse := make([]bool, n+1)
	q = []int{}
	for i := 1; i <= n; i++ {
		if f[i] == 2 {
			canReachUse[i] = true
