		q = q[1:]
		for _, v := range radj[u] {
			if !canReachUse[v] {
				canReachUse[v] = true
				q = append(q, v)
			}
		}
	}

	// Step 3: Find all assignment nodes
	assignNodes := []int{}
	for i := 1; i <= n; i++ {
		if f[i] == 1 {
			assignNodes = append(assignNodes, i)
		}
	}

	// Step 4: Find all use nodes
