		fmt.Fscan(reader, &a, &b)
		adj[a] = append(adj[a], b)
		revAdj[b] = append(revAdj[b], a)
	}

	// Step 1: Find all states reachable from any assignment (forward BFS)
	reachableFromAssign := make([]bool, n+1)
	q := []int{}
	for i := 1; i <= n; i++ {
		if f[i] == 1 {
			reachableFromAssign[i] = true
			q = append(q, i)
		}
	}
	for len(q) > 0 {
		u := q[0]
		q = q[1:]
		for _, v := range adj[u] {
			if !reachableFromAssign[v] {
				reachableFromAssign[v] = true
				q = append(q, v)
			}
		}
	}

	// Step 2: Find all states that can reach a usage (reverse BFS)
	canReachUse := make([]bool, n+1)
	q = []int{}
	for i := 1; i <= n; i++ {
		if f[i] == 2 {
			canReachUse[i] = true
			q = append(q, i)
		}
	}
	for len(q) > 0 {
		u := q[0]
		q = q[1:]
		for _, v := range revAdj[u] {
			if !canReachUse[v] {
				canReachUse[v] = true
				q = append(q, v)
			}
		}
	}

	// Step 3: Find states with assignment that can reach a usage without passing another assignment
	// Use reverse BFS from usages, but stop at assignments
	assignToValidUse := make([]bool, n+1)
	q = []int{}
	for i := 1; i <= n; i++ {
		if f[i] == 2 {
			assignToValidUse[i] = true
			q = append(q, i)
