				continue // Don't traverse further from assignments
			}
			if !assignToValidUse[v] {
				assignToValidUse[v] = true
				q = append(q, v)
			}
		}
	}

	// Step 4: Determine result for each state
	result := make([]int, n+1)
	for i := 1; i <= n; i++ {
