	for i := 1; i <= n; i++ {
		fmt.Fscan(reader, &f[i])
	}

	adj := make([][]int, n+1)
	revAdj := make([][]int, n+1)

	for i := 0; i < m; i++ {
		var a, b int
		fmt.Fscan(reader, &a, &b)
		adj[a] = append(adj[a], b)
		revAdj[b] = append(revAdj[b], a)
	}

	// Step 1: Find all nodes reachable from any assignment node (f[i] == 1)
	reachableFromAssign := make([]bool, n+1)
	queue := []int{}
	for i := 1; i <= n; i++ {
		if f[i] == 1 {
			reachableFromAssign[i] = true
			queue = append(queue, i)
		}
	}

	for len(queue) > 0 {
		u := queue[0]
		queue = queue[1:]
		for _, v := range adj[u] {
			if !reachableFromAssign[v] {
				reachableFromAssign[v] = true
				queue = append(queue, v)
			}
		}
	}

	// Step 2: Find all nodes that can reach a usage node (f[i] == 2)
	canReachUse := make([]bool, n+1)
	queue = []int{}
	for i := 1; i <= n; i++ {
		if f[i] == 2 {
			canReachUse[i] = true
			queue = append(queue, i)
		}
	}

	for len(queue) > 0 {
		u := queue[0]
		queue = queue[1:]
		for _, v := range revAdj[u] {
			if !canReachUse[v] {
				canReachUse[v] = true
				queue = append(queue, v)
			}
		}
	}

	// Step 3: For each node, check if it's on a path from assignment to usage
	// and no intermediate assignment exists
	result := make([]int, n+1)

	// We need to find nodes that are reachable from an assignment node,
	// can reach a usage node, and there's no assignment node between them
	// 
	// Approach: For each assignment node, do BFS/DFS to find all nodes reachable
	// without passing through another assignment node, and check if they can reach
	// a usage node

	visited := make([]bool, n+1)
	for i := 1; i <= n; i++ {
		if f[i] == 1 && !visited[i] {
			// BFS from this assignment node, stopping at other assignment nodes
			bfsQueue := []int{i}
			visited[i] = true
			for len(bfsQueue) > 0 {
				u := bfsQueue[0]
				bfsQueue = bfsQueue[1:]

				if canReachUse[u] {
					result[u] = 1
				}

				for _, v := range adj[u] {
					if !visited[v] && f[v] != 1 {
						visited[v] = true
						bfsQueue = append(bfsQueue, v)
					}
